
SELECT t_sortie_article.*,sum(t_sortie_article.qte_sort_art) as sortie,(SELECT SUM(t_approvisionnement_article.qte_appro_art) FROM t_approvisionnement_article where t_approvisionnement_article.mag_appro_art=21 AND t_sortie_article.art_sort_art=t_approvisionnement_article.art_appro_art) as qteApprovisionne,(select qte_stk from t_stock WHERE t_stock.art_stk=t_sortie_article.art_sort_art and t_stock.mag_stk=21) as stockqte,ifnull((select sum(qte_transf) from t_transfert WHERE mag_dst_transf=21 and art_transf=t_sortie_article.art_sort_art),0) as transfert_recu FROM `t_sortie_article`,t_sortie where t_sortie.mag_sort_src=21 and t_sortie.id_sort=t_sortie_article.sort_sort_art GROUP by t_sortie_article.art_sort_art

SELECT t_sortie_article.*,sum(t_sortie_article.qte_sort_art) as sortie,(SELECT SUM(t_approvisionnement_article.qte_appro_art) FROM t_approvisionnement_article where t_approvisionnement_article.mag_appro_art=2 AND t_sortie_article.art_sort_art=t_approvisionnement_article.art_appro_art) as qteApprovisionne,(select qte_stk from t_stock WHERE t_stock.art_stk=t_sortie_article.art_sort_art and t_stock.mag_stk=2) as stockqte,ifnull((select sum(qte_transf) from t_transfert WHERE mag_dst_transf=2 and art_transf=t_sortie_article.art_sort_art),0) as transfert_recu FROM `t_sortie_article`,t_sortie where t_sortie.mag_sort_src=2 and t_sortie.id_sort=t_sortie_article.sort_sort_art GROUP by t_sortie_article.art_sort_art;